#!/usr/bin/env node
/**
 * Generates airflow-notes.md, airflow-interview.md, airflow-practice-questions.json
 * Run: node scripts/generate-airflow-content.mjs
 */
import fs from "fs";
import path from "path";

const root = path.join(import.meta.dirname, "..");
const topicsDir = path.join(root, "content/topics");
const dataDir = path.join(root, "src/data");

function block(t) {
  const lines = [
    `### ${t.n}. ${t.title}`,
    "",
    `**Concept:** ${t.concept}`,
    "",
  ];
  if (t.syntax) {
    lines.push("**Syntax:**", "", "```python", t.syntax.trim(), "```", "");
  }
  lines.push(`**Example:** ${t.example}`, "", `**DE example:** ${t.de}`, "");
  lines.push(`**Common mistake:** ${t.mistake}`, "", `**Interview:** ${t.interview}`, "");
  if (t.practice) lines.push(`**Practice:** ${t.practice}`, "");
  lines.push("");
  return lines.join("\n");
}

